-- first page
select "f"."source_id", "f"."item_kind", "f"."item_type", "f"."title", "f"."summary", "f"."author_member_id", "f"."neighborhood_id", "f"."animal_interest_code", "f"."status", "f"."created_at", "f"."updated_at", "f"."target_path" from "townpet_public_feed_item" as "f" where true order by "f"."created_at" desc, "f"."item_kind" asc, "f"."source_id" desc fetch next ? rows only
-- next cursor
select "f"."source_id", "f"."item_kind", "f"."item_type", "f"."title", "f"."summary", "f"."author_member_id", "f"."neighborhood_id", "f"."animal_interest_code", "f"."status", "f"."created_at", "f"."updated_at", "f"."target_path" from "townpet_public_feed_item" as "f" where (true and ("f"."created_at" < cast(? as timestamp with time zone) or ("f"."created_at" = cast(? as timestamp with time zone) and ("f"."item_kind" > ? or ("f"."item_kind" = ? and "f"."source_id" < cast(? as uuid)))))) order by "f"."created_at" desc, "f"."item_kind" asc, "f"."source_id" desc fetch next ? rows only